def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    """
    from krake.data.kubernetes.observer import ObserverEntry
    from krake.resource import K8sResource

    def default_observer_schema(resource_type):
        """Default observer schema for the given Kubernetes resource type."""
        return {
            'type': type(resource_type).__name__,
            'fields': {
                'name': {
                    'type': 'str',
                    'description': 'The name of the observer.'
                },
                'spec': {
                    'type': 'dict',
                    'description': 'The specification of the observer.'
                },
                'status': {
                    'type': 'dict',
                    'description': 'The status of the observer.'
                },
            }
        }

    for entry in app.spec.manifest:
        if not isinstance(entry, K8sResource):
            continue

        resource_name = entry.name
        resource_type = entry.resource_type

        default_schema = default_observer_schema(resource_type)

        # Assuming app.observer_schema is a dictionary where the keys are resource types
        if resource_type in app.observer_schema:
            continue

        # If default schema isn't in observer_schema add it
        app.observer_schema[resource_type] = default_schema

def generate_default_observer_schema(app):
    for resource_name, spec in app.spec.manifest.items():
        if 'custom_observer_schema' not in spec:
            default_observer = {
                'api_group': 'kraken.k8s.io/groups/observer',
                'kind': 'DefaultObserver',
                'metadata': {
                    'name': f'default-observer-{resource_name}'
                },
                'spec': {
                    'resource': resource_name,
                    'scans': ['Always']
                }
            }
            app.spec.observers.append(copy.deepcopy(default_observer))

def generate_default_observer_schema(self, app):
        """Generate the default observer schema for each Kubernetes resource present in
        ``spec.manifest`` for which a custom observer schema hasn't been specified.

        Args:
            app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
        """
        import json
        import itertools
        from defusedxml.ElementTree import fromstring
        from jsonpointer import resolve_pointer

        # Create a dictionary to store the observed schema for each resource type
        observed_schemas = {}

        # Iterate over each non-empty resource type in the manifest
        for resource_type in [resource_type for resource_type in self.spec.manifest if resource_type]:
            # Fetch the controllable specification for the resource type
            controllable_spec = resolve_pointer(self.spec.for_resource(resource_type), 'spec')

            # Generate a default observer schema for the resource type
            observer_schema = {
                'type': 'object',
                'properties': {
                    'metadata': {
                        'type': 'object',
                        'properties': {
                            'name': {
                                'type': 'string'
                            }
                        },
                        'required': ['name']
                    },
                    'resource': {
                        'type': 'string'
                    },
                    'data': {
                        'type': 'object',
                        'properties': {},
                        'required': []
                    }
                },
                'required': ['metadata', 'resource', 'data']
            }

            # Merge the controllable specification with the default observer schema
            observer_schema.update(controllable_spec)

            # Add the observer schema to the dictionary with the resource type as the key
            observed_schemas[resource_type] = observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
