def deep_merge_nodes(nodes):
    """Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """

    def merge_nodes(merged, nodes):
        merged_dict = {}
        for key, value in nodes:
            if key in merged_dict:
                if isinstance(value, dict):
                    merged_dict[key] = merge_nodes(merged_dict[key], [(key, value)])
                else:
                    merged_dict[key] = value
            else:
                merged_dict[key] = value
        return {x: y for x, y in merged_dict.items() if isinstance(y, dict)}

    return [merge_nodes({}, [node]) for node in nodes if isinstance(node, list)]

def deep_merge_nodes(nodes):
    merged_values = {}
    for key, value in nodes:
        if key not in merged_values:
            merged_values[key] = value
        else:
            if not isinstance(value, dict) or not isinstance(merged_values[key], dict):
                if isinstance(value, dict) or isinstance(merged_values[key], dict):
                    raise ValueError("Incompatible node values")
                merged_values[key] = value
            else:
                merged_values[key] = deep_merge_nodes(value.items() + merged_values[key].items())
    return [(key, value) for key, value in merged_values.items()]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    merged_nodes = []

    for key, value in nodes:
        if isinstance(value, MappingNode):
            result = {k: deep_merge_nodes(v) for k, v in value.items()}
        else:
            result = value

        # Find the existing node with the same key
        for idx in range(len(merged_nodes)):
            if merged_nodes[idx][0] == key:
                # Merge the nodes if they have the same key
                merged_nodes[idx] = (key, deep_merge_values(result, merged_nodes[idx][1]))
                break
        else:
            # Add the new node if no existing node has the same key
            merged_nodes.append((key, result))

    return merged_nodes

def deep_merge_nodes(nodes):
    # Create a mapping to store the merged node values
    merged_map = {}

    for key, value in nodes:
        # If the key already exists in the map, merge the values
        if key in merged_map:
            # Merge dictionaries if the values are also dictionaries
            if isinstance(merged_map[key], dict) and isinstance(value, dict):
                merged_map[key] = {**merged_map[key], **value}
            # Otherwise, append the new value if it's not a dictionary
            else:
                merged_map[key] = [merged_map[key], value]
        # Otherwise, just add the key-value pair
        else:
            merged_map[key] = value

    return list(merged_map.items())

def deep_merge_nodes(nodes):
    merged_nodes = defaultdict(dict)

    for value in nodes:
        key_node, value_node = value
        key_value = key_node.value

        if value_node.tag in ("tag:yaml.org,2002:map", "tag:yaml.org,2002:set"):
            if key_value in merged_nodes:
                merged_nodes[key_value] = default_merge(merged_nodes[key_value], value_node.value)
            else:
