    COMPREPLY=()
    FZF_DEFAULT_OPTS=""
    ARG_POSITIONAL=("$@")

    # Parse arguments
    options_list=({', '.join(options)})
    main_options=({', '.join(['-{}'.format(option) for option in options if not option.startswith('--')])})
    for arg in ARG_POSITIONAL:
