def paging(response, max_results):
    total_results = len(response)
    for start_index in range(0, total_results, max_results):
        end_index = min(start_index + max_results, total_results)
        yield response[start_index:end_index]

def paging(response, max_results):
    while response:
        yield response[0:max_results]
        response = response[max_results:]

page_index = 1
    while page_index * max_results <= len(response):
        page = response[page_index * max_results - max_results: page_index * max_results]
        if not page:
            if page_index * max_results != len(response):
                last_page = page[-1]
                while last_page['next_page'] or len(page) != 0:
                    if len(page) != 0:
                        page = page + response[page_index * max_results - max_results: page_index * max_results]
                    last_page = last_page['next_page']
                page = response[page_index * max_results - max_results: page_index * max_results + 1]
            break
        yield page
        page_index += 1

