def hist_to_graph(hist: List[float], make_value: Optional[callable] = None,
                   get_coordinate: str = "left", field_names: Tuple[str, ...] = ("x", "y"),
                   scale: Optional[float] = None) -> 'graph':
    if make_value is None:
        make_value = lambda bin_: bin_
    if (make_value is not None and startswith(make_value, '<')) or hasattr(hist, '__getitem__'):
        if scale is None:
            scale = np.sqrt(np.mean(np.square(hist)))
        if scale <= 0:
            scale = 1
        bins = [make_value(hist[i]) for i in range(len(hist))]
    else:
        if make_value is not None:
            raise ValueError("make_value must be a function that accepts a value without context")
        bins = [make_value(i) for i in range(len(hist))]

    max_length = min(max(len(str(b)) for b in bins), 10)
    max_val = max(bins)
    max_val_length = max(len(format(max_val, ".2f")))

    term_width = get_terminal_size()[0]
    max_bar_width = term_width - MARGIN - (max_length + 3 + max_val_length + 3)
    template = f"{field_names[0]:>{max_length}} [ {field_names[1]:>{max_val_length}} ] {TICK}"
    for i in range(len(bins)):
        key, value = bins[i].split(' ')
        try:
            bar = int(math.ceil(max_bar_width * float(value) / max_val)) * TICK
        except ValueError:
            bar = ''
        line = template.format(
            key=key,
            value=format(float(value), ".2f"),
            bar=bar,
            max_length=max_length,
            max_val_length=max_val_length
        )
        print(line)
    return ''.join(lines)

